#include<bits/stdc++.h>
using namespace std;

int n,x,ans;

int check(int k,int x)  
{
	int num=0;  
	while (k)  
	{
		if (k%10==x) num++;  
		k/=10;  
	}
	return num;
}

int main()
{
	cin>>n>>x;
	for (int i=1;i<=n;i++)  
	{
		ans+=check(i,x);
	}
	cout<<ans<<"\n";
	return 0;
}

#include<iostream>
#include<cstdio>
using namespace std;
int main(){
    int n,x,m=1,ans=0;
    scanf("%d%d",&n,&x);
    while(m<=n){
        int a=n/(m*10),b=n/m%10,c=n%m;  
        if(x){
            if(b>x) ans+=(a+1)*m;  
            if(b==x) ans+=a*m+c+1;  
            if(b<x) ans+=a*m;  
        }
        else{  
            if(b) ans+=a*m;
            else ans+=(a-1)*m+c+1;
        }
        m*=10;
    }
    printf("%d\n",ans);
    return 0;
}
